INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("どうもありがとう♪\nそれにしても素晴らしいケーキだね、\nボクのために用意してくれたの？", 1, 10, 0.5, 100811, 0, 0, 11, 23814, 23814084, 1);
