INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("それじゃ、味わって食べなくちゃね！\nあなたも来てくれてありがとう！\nそうだ、みんなで記念の一枚を撮ろう！\n映写魔法を覚えたから、私に任せて♪", 1, 10, 0.5, 109211, 0, 0, 11, 29014, 29014073, 1);
