INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("そ、それはまた別の話でしょう！？\n私が言いたいのは……！", 1, 10, 0.5, 106411, 0, 0, 11, 30314, 30314085, 1);
