INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("わかっております、シェフィさま。\nそれでも……お二人は、あなたを\n大切に想っているのです。\nもちろん、わたくしと主さまも。", 1, 10, 0.5, 105911, 0, 0, 11, 30314, 30314090, 1);
