INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("wac_birthday_talk_smile", "", 1, "", 100711, "", 0.2, 3, 31114, 31114074, "");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("vo_wac_31114_001", 0, 0, "", "vo_wac_31114", "", "", 21, 31114, 31114075, "");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("それならプリンがいいの～！\nこのケーキと同じくらい、でっかい\nプリンが食べたいの～！", 1, 10, 0.5, 100711, 0, 0, 11, 31114, 31114076, 1);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("", "", "", "", 0, "", "", 91, 31114, 31114077, "");
