INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("えっとさー、その～……\n普段あんまりお仕事してないのに、\nこんな大げさにお祝いされると\n気まずいっていうか～……", 1, 10, 0.5, 102611, 0, 0, 11, 32114, 32114065, 1);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("", "", "", "", 0, "", "", 91, 32114, 32114066, "");
