INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES ("麦しゅわの助けも借りながら、\nみんなで協力して、\n全部乗り越えることができたもの！", 1, 10, 0.5, 103411, 0, 0, 11, 39114, 39114078, 1);
